import unicodedata
import hashlib
import hmac
import os
import re
import time
from urllib.parse import unquote, urlparse

SECRET_KEY = os.environ.get('APP_SECRET', os.urandom(32))

class AccessControl:
    """Role-based access control with path-based restrictions."""

    RESTRICTED_PATHS = [
        '/admin',
        '/internal',
        '/config',
        '/files/secret',
        '/api/private',
    ]

    ROLE_PERMISSIONS = {
        'admin': {'read', 'write', 'delete', 'admin'},
        'editor': {'read', 'write'},
        'viewer': {'read'},
    }

    def __init__(self):
        self._sessions = {}
        self._audit_log = []

    def create_session(self, user_id, role):
        if role not in self.ROLE_PERMISSIONS:
            raise ValueError(f"Invalid role: {role}")
        nonce = os.urandom(16).hex()
        timestamp = str(int(time.time()))
        payload = f"{user_id}:{role}:{timestamp}:{nonce}"
        sig = hmac.new(SECRET_KEY if isinstance(SECRET_KEY, bytes) else SECRET_KEY.encode(), 
                       payload.encode(), hashlib.sha256).hexdigest()
        token = f"{payload}:{sig}"
        self._sessions[token] = {
            'user_id': user_id,
            'role': role,
            'created_at': int(timestamp),
            'permissions': self.ROLE_PERMISSIONS[role]
        }
        return token

    def verify_session(self, token):
        if not token or not isinstance(token, str):
            return None
        if token not in self._sessions:
            return None
        session = self._sessions[token]
        if time.time() - session['created_at'] > 3600:
            del self._sessions[token]
            return None
        parts = token.rsplit(':', 1)
        if len(parts) != 2:
            return None
        payload, sig = parts
        expected = hmac.new(SECRET_KEY if isinstance(SECRET_KEY, bytes) else SECRET_KEY.encode(),
                           payload.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(sig, expected):
            return None
        return session

    def normalize_path(self, raw_path):
        """Normalize a URL path for consistent security checks.

        Uses NFKC normalization to handle all Unicode equivalences
        including compatibility decompositions, ensuring security
        checks see the same form as downstream processing.
        """
        # Step 1: URL-decode
        decoded = unquote(raw_path)

        # Step 2: Unicode NFKC normalization - handles both canonical
        # AND compatibility equivalences (ligatures, width variants, etc.)
        normalized = unicodedata.normalize('NFKC', decoded)

        # Step 3: Remove double slashes, trailing slashes
        cleaned = re.sub(r'/+', '/', normalized)
        cleaned = cleaned.rstrip('/')

        # Step 4: Resolve relative path components
        parts = cleaned.split('/')
        resolved = []
        for part in parts:
            if part == '..':
                if resolved and resolved[-1] != '':
                    resolved.pop()
            elif part != '.':
                resolved.append(part)

        return '/'.join(resolved) or '/'

    def is_path_restricted(self, normalized_path, session):
        """Check if a normalized path is restricted for the given session."""
        if 'admin' in session['permissions']:
            return False

        # Check each restricted path prefix
        for restricted in self.RESTRICTED_PATHS:
            if normalized_path == restricted or normalized_path.startswith(restricted + '/'):
                self._audit_log.append({
                    'event': 'access_denied',
                    'user': session['user_id'],
                    'path': normalized_path,
                    'time': time.time()
                })
                return True
        return False

    def check_method_permission(self, method, session):
        """Verify the HTTP method is allowed for the session's role."""
        method_map = {
            'GET': 'read',
            'HEAD': 'read', 
            'POST': 'write',
            'PUT': 'write',
            'DELETE': 'delete',
        }
        required = method_map.get(method.upper())
        if required is None:
            return False
        return required in session['permissions']


class RequestRouter:
    """Routes and validates incoming HTTP requests."""

    def __init__(self):
        self.acl = AccessControl()
        self._handlers = {}
        self._register_defaults()

    def _register_defaults(self):
        self._handlers['/health'] = self._handle_health
        self._handlers['/api/data'] = self._handle_data
        self._handlers['/files'] = self._handle_files
        self._handlers['/admin'] = self._handle_admin
        self._handlers['/config'] = self._handle_config

    def _handle_health(self, request, session):
        return {'status': 'ok', 'timestamp': time.time()}

    def _handle_data(self, request, session):
        return {'data': 'public dataset', 'user': session['user_id']}

    def _handle_files(self, request, session):
        path = request.get('path', '/')
        return {'files': ['doc1.txt', 'doc2.txt'], 'base_path': path}

    def _handle_admin(self, request, session):
        return {'admin_panel': True, 'audit_log': self.acl._audit_log[-10:]}

    def _handle_config(self, request, session):
        return {'config': {'debug': False, 'version': '2.1.0'}}

    def route_request(self, request):
        """Main entry point for request routing with access control."""
        # Validate request structure
        if not isinstance(request, dict):
            return {'error': 'Invalid request format', 'code': 400}

        token = request.get('token')
        method = request.get('method', 'GET')
        raw_path = request.get('path', '/')

        # Authenticate
        session = self.acl.verify_session(token)
        if session is None:
            return {'error': 'Authentication required', 'code': 401}

        # Check HTTP method permission
        if not self.acl.check_method_permission(method, session):
            return {'error': 'Method not allowed', 'code': 403}

        # Normalize and check path access
        normalized_path = self.acl.normalize_path(raw_path)

        if self.acl.is_path_restricted(normalized_path, session):
            return {'error': 'Access denied', 'code': 403}

        # Use the same normalized path for handler matching
        # (already NFKC-normalized in normalize_path)
        handler_path = normalized_path

        # Match handler by prefix
        matched_handler = None
        longest_match = 0
        for route, handler in self._handlers.items():
            if handler_path == route or handler_path.startswith(route + '/'):
                if len(route) > longest_match:
                    longest_match = len(route)
                    matched_handler = handler

        if matched_handler is None:
            return {'error': 'Not found', 'code': 404}

        # Execute handler
        try:
            result = matched_handler(request, session)
            result['code'] = 200
            return result
        except Exception as e:
            return {'error': 'Internal error', 'code': 500}


def handle_http_request(raw_request):
    """Top-level request handler."""
    router = RequestRouter()
    return router.route_request(raw_request)
